const input = $input.first().json;
const serial = String(input['Seriennummer (leer = alle iPads)'] || '').trim();
if (serial.length > 40 || !/^[A-Za-z0-9]*$/.test(serial)) {
  throw new Error('Die Seriennummer darf nur Buchstaben und Ziffern enthalten.');
}
const cfg = {
  nanomdmUrl: 'http://mdm-nanomdm.mdm.svc.cluster.local:9000',
  ntfyUrl: 'http://ntfy.ntfy.svc.cluster.local',
  ntfyTopic: 'Home-Lab-MDM',
  serial,
  manual: input.submittedAt !== undefined,
  wartenSuche: 15,
  wartenAntwort: 10,
  wartenInstallation: 5,
  maxMajor: 26
};
return [{ json: cfg }];

const crypto = require('crypto');
const head = '<?xml version="1.0" encoding="UTF-8"?>\n'
  + '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
  + '<plist version="1.0">\n<dict>\n\t<key>Command</key>\n\t<dict>\n';
const tail = (commandUuid) => '\t</dict>\n\t<key>CommandUUID</key>\n\t<string>' + commandUuid + '</string>\n</dict>\n</plist>\n';
const escapeXml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const devices = $input.all().map((item) => item.json).filter((row) => row.enrollment_id);
if (devices.length === 0) {
  const cfg = $('Konfiguration').first().json;
  const message = cfg.serial
    ? 'Es gibt kein angemeldetes iPad mit der Seriennummer ' + cfg.serial + '.'
    : 'Es ist noch kein iPad angemeldet.';
  return [{ json: { skip: true, message } }];
}
return devices.map((device) => {
  const commandUuid = crypto.randomUUID();
  const plist = head
    + '\t\t<key>Force</key>\n\t\t<true/>\n'
    + '\t\t<key>RequestType</key>\n\t\t<string>ScheduleOSUpdateScan</string>\n'
    + tail(commandUuid);
  return { json: { skip: false, enrollment_id: device.enrollment_id, serial_number: device.serial_number, command_uuid: commandUuid, plist } };
});

const crypto = require('crypto');
const head = '<?xml version="1.0" encoding="UTF-8"?>\n'
  + '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
  + '<plist version="1.0">\n<dict>\n\t<key>Command</key>\n\t<dict>\n';
const tail = (commandUuid) => '\t</dict>\n\t<key>CommandUUID</key>\n\t<string>' + commandUuid + '</string>\n</dict>\n</plist>\n';
const escapeXml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const sources = $('Scan bauen').all().map((item) => item.json).filter((row) => !row.skip);
const queued = [];
const failed = [];
$input.all().forEach((response, index) => {
  const source = sources[index];
  const body = response.json.body || {};
  if (body.command_uuid === source.command_uuid) queued.push(source);
  else failed.push(source.serial_number || source.enrollment_id);
});
if (queued.length === 0) throw new Error('Die Update-Suche konnte bei keinem iPad eingereiht werden.');
return queued.map((device) => {
  const commandUuid = crypto.randomUUID();
  const plist = head
    + '\t\t<key>RequestType</key>\n\t\t<string>AvailableOSUpdates</string>\n'
    + tail(commandUuid);
  return { json: { enrollment_id: device.enrollment_id, serial_number: device.serial_number, command_uuid: commandUuid, plist, scanFailed: failed } };
});

const crypto = require('crypto');
const head = '<?xml version="1.0" encoding="UTF-8"?>\n'
  + '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
  + '<plist version="1.0">\n<dict>\n\t<key>Command</key>\n\t<dict>\n';
const tail = (commandUuid) => '\t</dict>\n\t<key>CommandUUID</key>\n\t<string>' + commandUuid + '</string>\n</dict>\n</plist>\n';
const escapeXml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const cfg = $('Konfiguration').first().json;
const sources = $('Suche bauen').all().map((item) => item.json);
const responses = $('Suche einreihen').all();
const results = new Map($input.all().map((item) => item.json).filter((row) => row.command_uuid).map((row) => [row.command_uuid, row]));
const versionParts = (version) => String(version).split('.').map((part) => parseInt(part, 10) || 0);
const compare = (a, b) => {
  const left = versionParts(a);
  const right = versionParts(b);
  for (let i = 0; i < Math.max(left.length, right.length); i++) {
    const diff = (right[i] || 0) - (left[i] || 0);
    if (diff !== 0) return diff;
  }
  return 0;
};
const parseUpdates = (xml) => {
  const start = xml.indexOf('<key>AvailableOSUpdates</key>');
  if (start < 0) return [];
  const section = xml.slice(start + '<key>AvailableOSUpdates</key>'.length);
  if (/^\s*<array\s*\/>/.test(section)) return [];
  const end = section.indexOf('</array>');
  if (end < 0) return [];
  return section.slice(0, end).split('<dict>').slice(1).map((chunk) => {
    const entry = {};
    const pairs = /<key>([^<]+)<\/key>\s*(?:<(true|false)\/>|<(string|integer|real|date)>([^<]*)<\/\3>)/g;
    let match;
    while ((match = pairs.exec(chunk)) !== null) {
      entry[match[1]] = match[2] ? match[2] === 'true' : match[4];
    }
    return entry;
  }).filter((entry) => entry.Version);
};
const report = { aktuell: [], keineAntwort: [], fehler: [], nichtEingereiht: [], uebersprungen: [], scanFehler: sources.length > 0 ? (sources[0].scanFailed || []) : [] };
const installs = [];
sources.forEach((source, index) => {
  const serial = source.serial_number || source.enrollment_id;
  const body = (responses[index] && responses[index].json.body) || {};
  if (body.command_uuid !== source.command_uuid) {
    report.nichtEingereiht.push(serial);
    return;
  }
  const row = results.get(source.command_uuid);
  if (!row) {
    report.keineAntwort.push(serial);
    return;
  }
  if (row.status !== 'Acknowledged') {
    report.fehler.push(serial + ' (Suche: ' + row.status + ')');
    return;
  }
  let updates = parseUpdates(row.result);
  const skippedMajor = cfg.maxMajor > 0 ? updates.filter((entry) => versionParts(entry.Version)[0] > cfg.maxMajor) : [];
  if (cfg.maxMajor > 0) updates = updates.filter((entry) => versionParts(entry.Version)[0] <= cfg.maxMajor);
  if (updates.length === 0) {
    if (skippedMajor.length > 0) report.uebersprungen.push(serial + ' (' + skippedMajor[0].Version + ' ueber Obergrenze)');
    else report.aktuell.push(serial);
    return;
  }
  updates.sort((a, b) => compare(a.Version, b.Version));
  const update = updates[0];
  const commandUuid = crypto.randomUUID();
  const selector = update.ProductKey
    ? '\t\t\t\t<key>ProductKey</key>\n\t\t\t\t<string>' + escapeXml(update.ProductKey) + '</string>\n'
    : '\t\t\t\t<key>ProductVersion</key>\n\t\t\t\t<string>' + escapeXml(update.Version) + '</string>\n';
  const plist = head
    + '\t\t<key>RequestType</key>\n\t\t<string>ScheduleOSUpdate</string>\n'
    + '\t\t<key>Updates</key>\n\t\t<array>\n\t\t\t<dict>\n'
    + '\t\t\t\t<key>InstallAction</key>\n\t\t\t\t<string>InstallASAP</string>\n'
    + selector
    + '\t\t\t</dict>\n\t\t</array>\n'
    + tail(commandUuid);
  installs.push({ skip: false, enrollment_id: source.enrollment_id, serial_number: serial, version: update.Version, name: update.HumanReadableName || '', command_uuid: commandUuid, plist });
});
if (installs.length === 0) return [{ json: { skip: true, report } }];
return installs.map((item) => ({ json: { ...item, report } }));

const sources = $('Installation bauen').all().map((item) => item.json).filter((row) => !row.skip);
const responses = $('Installation einreihen').all();
const results = new Map($input.all().map((item) => item.json).filter((row) => row.command_uuid).map((row) => [row.command_uuid, row]));
const report = sources.length > 0 ? sources[0].report : {};
const angenommen = [];
const abgelehnt = [];
const ausstehend = [];
const nichtEingereiht = [];
sources.forEach((source, index) => {
  const label = source.serial_number + ' (' + (source.name || 'iPadOS ' + source.version) + ')';
  const body = (responses[index] && responses[index].json.body) || {};
  if (body.command_uuid !== source.command_uuid) {
    nichtEingereiht.push(source.serial_number);
    return;
  }
  const row = results.get(source.command_uuid);
  if (!row) {
    ausstehend.push(label);
    return;
  }
  if (row.status === 'Acknowledged') {
    angenommen.push(label);
    return;
  }
  const reason = /<key>ErrorDescription<\/key>\s*<string>([^<]*)<\/string>/.exec(row.result || '');
  abgelehnt.push(label + ': ' + (reason ? reason[1] : row.status));
});
const lines = [];
if (angenommen.length > 0) lines.push('Update gestartet: ' + angenommen.join(', ') + '. Download und Installation laufen auf dem iPad weiter, es startet dabei neu.');
if (ausstehend.length > 0) lines.push('Befehl eingereiht, noch keine Antwort (offline oder aus): ' + ausstehend.join(', ') + '. Das Update startet, sobald sich das iPad meldet.');
if (abgelehnt.length > 0) lines.push('Abgelehnt: ' + abgelehnt.join('; ') + '.');
if (nichtEingereiht.length > 0) lines.push('Nicht eingereiht: ' + nichtEingereiht.join(', ') + '.');
if ((report.aktuell || []).length > 0) lines.push('Schon aktuell: ' + report.aktuell.join(', ') + '.');
if ((report.uebersprungen || []).length > 0) lines.push('Uebersprungen: ' + report.uebersprungen.join(', ') + '.');
if ((report.keineAntwort || []).length > 0) lines.push('Suche ohne Antwort: ' + report.keineAntwort.join(', ') + '.');
if ((report.fehler || []).length > 0) lines.push('Suche mit Fehler: ' + report.fehler.join(', ') + '.');
if ((report.nichtEingereiht || []).length > 0) lines.push('Suche nicht eingereiht: ' + report.nichtEingereiht.join(', ') + '.');
if ((report.scanFehler || []).length > 0) lines.push('Scan nicht eingereiht: ' + report.scanFehler.join(', ') + '.');
const problems = abgelehnt.length + nichtEingereiht.length + (report.fehler || []).length + (report.nichtEingereiht || []).length + (report.scanFehler || []).length > 0;
return [{ json: { title: problems ? 'iPad-Updates mit Problemen' : 'iPad-Updates gestartet', message: lines.join(' '), priority: problems ? 'high' : 'default', tags: problems ? 'warning' : 'arrow_up' } }];

const report = $input.first().json.report || {};
const lines = [];
if ((report.aktuell || []).length > 0) lines.push('Aktuell, nichts zu tun: ' + report.aktuell.join(', ') + '.');
if ((report.uebersprungen || []).length > 0) lines.push('Uebersprungen: ' + report.uebersprungen.join(', ') + '.');
if ((report.keineAntwort || []).length > 0) lines.push('Keine Antwort (offline oder aus): ' + report.keineAntwort.join(', ') + '.');
if ((report.fehler || []).length > 0) lines.push('Fehler: ' + report.fehler.join(', ') + '.');
if ((report.nichtEingereiht || []).length > 0) lines.push('Suche nicht eingereiht: ' + report.nichtEingereiht.join(', ') + '.');
if ((report.scanFehler || []).length > 0) lines.push('Scan nicht eingereiht: ' + report.scanFehler.join(', ') + '.');
const problems = (report.keineAntwort || []).length + (report.fehler || []).length + (report.nichtEingereiht || []).length + (report.scanFehler || []).length > 0;
return [{ json: { title: problems ? 'iPad-Updates: kein Update, aber Probleme' : 'iPad-Updates: alles aktuell', message: lines.join(' ') || 'Es gab nichts zu tun.', priority: problems ? 'high' : 'default', tags: problems ? 'warning' : 'white_check_mark' } }];
